"""Reusable helpers for the block-stacking task."""
import numpy as np
from robot import tools, query, target, handoff
from ora_lib import current, object_geometry, Direction, Point

CAM = "head"
JAW_OFF = 0.1501          # nominal jaw contact centre along the approach axis from link6

def candidates(color, cam=CAM):
    r = tools.vision_ground(camera=cam, text=color + " block")
    return r["result"].get("candidates", [])

def mean_rgb(obs, cand, cam=CAM):
    try:
        t = obs.target(cand["target_ref"])
        m = np.asarray(t.mask).astype(bool)
        rgb = np.asarray(obs.camera(cam).rgb)
        vals = rgb[m].reshape(-1, 3)
        return vals.mean(axis=0), int(m.sum())
    except Exception as e:
        return None, 0

def list_blocks(color, obs, cam=CAM, xmin=-0.55, xmax=0.55):
    out = []
    for c in candidates(color, cam):
        try:
            g = object_geometry(c)
        except Exception:
            continue
        if g.status != "localized" or g.support_z_m is None:
            continue
        cx, cy, cz = g.center_xyz_m
        if not (xmin <= cx <= xmax):
            continue
        mrgb, n = mean_rgb(obs, c, cam)
        out.append(dict(cand=c, geom=g, rgb=mrgb, npts=n))
    return out

def yaw_axes(g):
    """Yaw of the measured footprint's principal horizontal axis, as a unit world Direction."""
    ax = np.array(g.principal_axes_world, dtype=float)
    # pick the row with the smallest |z| component -> horizontal axis
    i = int(np.argmin(np.abs(ax[:, 2])))
    v = ax[i].copy()
    v[2] = 0.0
    v /= np.linalg.norm(v)
    return Direction(v, "world")

def top_of(g):
    return float(g.support_z_m + g.height_above_support_m)

"""Colour-validated block identification from several public views."""
import numpy as np
from robot import tools
from ora_lib import object_geometry
from policy import mean_rgb, aabb_center_xy

REF = {"green": np.array([43.0, 231.0, 37.0]),
       "cyan":  np.array([128.0, 231.0, 229.0]),
       "yellow": np.array([236.0, 234.0, 23.0])}
COL_MAX_DIST = 90.0
DEDUP_M = 0.02

def classify(rgb):
    if rgb is None:
        return None, 1e9
    best, bd = None, 1e9
    for k, ref in REF.items():
        d = float(np.linalg.norm(np.asarray(rgb, float) - ref))
        if d < bd:
            best, bd = k, d
    return (best if bd <= COL_MAX_DIST else None), bd

def blocks_from(camera, color, obs):
    r = tools.vision_ground(camera=camera, text=color + " block")
    out = []
    for c in (r["result"].get("candidates") or []):
        try:
            g = object_geometry(c)
        except Exception:
            continue
        if g.status != "localized":
            continue
        rgb, n = mean_rgb(obs, c, camera)
        cls, dist = classify(rgb)
        out.append(dict(camera=camera, cand=c, geom=g, rgb=rgb, cls=cls, coldist=dist, npts=n))
    return out

def scan(obs, colors=("green", "cyan", "yellow"), cameras=("head", "left_wrist", "right_wrist")):
    rows = []
    for cam in cameras:
        for color in colors:
            try:
                rows.extend(blocks_from(cam, color, obs))
            except Exception as e:
                print("scan error", cam, color, type(e).__name__, e)
    return rows

def best_block(rows, color, min_pts=100):
    """Pick the candidate classified as `color` with the most supporting evidence."""
    cands = [r for r in rows if r["cls"] == color and r["npts"] >= min_pts and r["geom"].support_z_m is not None]
    # merge duplicates by world position
    groups = []
    for r in cands:
        c = aabb_center_xy(r["geom"])
        for grp in groups:
            if np.hypot(*(np.array(grp[0]["c"]) - c)[:2]) < DEDUP_M:
                grp.append(dict(r, c=c)); break
        else:
            groups.append([dict(r, c=c)])
    if not groups:
        return None, []
    # prefer the view with the most mask points, then head
    groups.sort(key=lambda grp: -max(g["npts"] for g in grp))
    g0 = max(groups[0], key=lambda g: g["npts"])
    return g0, groups

